class FakeRedis:
    """Minimal async Redis stand-in backed by a dict."""

    def __init__(self) -> None:
        self.data: dict[str, str] = {}

    async def scan_iter(self, match: str = "*", count: int = 100):
        prefix = match.rstrip("*")
        for k in list(self.data):
            if k.startswith(prefix):
                yield k

    async def get(self, key: str) -> str | None:
        return self.data.get(key)

    async def setex(self, key: str, ttl: int, value: str) -> None:
        self.data[key] = value

    async def delete(self, key: str) -> None:
        self.data.pop(key, None)


VECTORS = {"leave policy": [1.0, 0.0], "leave rules": [0.95, 0.31], "pay day": [0.0, 1.0]}


def _cache(backend: str = "redis", redis: object | None = None) -> SemanticCache:
    """Build a cache with deterministic 2-d embeddings."""
    embedder = Mock(embed=lambda q: VECTORS[q])
    cfg = YamlAppConfig(cache=CacheConfig(backend=backend, similarity_threshold=0.9))
    return SemanticCache(cfg, redis or FakeRedis(), embedder)


@pytest.mark.asyncio
async def test_lookup_is_scoped_to_collection() -> None:
    cache = _cache()
    await cache.store("leave policy", {"answer": "A-hr"}, "hr")
    assert await cache.lookup("leave policy", "hr") == {"answer": "A-hr"}
    assert await cache.lookup("leave policy", "finance") is None
    assert await cache.lookup("leave policy", None) is None
    await cache.store("leave policy", {"answer": "A-all"}, None)
    assert await cache.lookup("leave policy", None) == {"answer": "A-all"}
    assert await cache.lookup("leave policy", "hr") == {"answer": "A-hr"}


